create table if not exists public.booking_settings (company_id uuid primary key references public.companies(id) on delete cascade, enabled boolean not null default false, slug text unique, slot_interval_minutes integer not null default 30 check (slot_interval_minutes in (15,20,30,60)), min_notice_hours integer not null default 2 check (min_notice_hours between 0 and 720), max_days_ahead integer not null default 60 check (max_days_ahead between 1 and 365), require_address boolean not null default true, updated_at timestamptz not null default now());
create table if not exists public.booking_services (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id) on delete cascade, name text not null, description text, duration_minutes integer not null default 60 check (duration_minutes between 1 and 480), price numeric(12,2), active boolean not null default true, display_order integer not null default 0, created_at timestamptz not null default now());
create index if not exists booking_services_company_idx on public.booking_services(company_id,active,display_order);
create table if not exists public.booking_hours (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id) on delete cascade, day_of_week integer not null check(day_of_week between 0 and 6), open_time time not null, close_time time not null, enabled boolean not null default true, unique(company_id,day_of_week), check(close_time>open_time));
create table if not exists public.booking_requests (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id) on delete cascade, service_id uuid references public.booking_services(id) on delete set null, customer_id uuid references public.customers(id) on delete set null, job_id uuid references public.jobs(id) on delete set null, requested_date date not null, requested_time time not null, customer_name text not null, customer_phone text, customer_email text, customer_address text, notes text, status text not null default 'confirmed' check(status in('confirmed','cancelled','pending')), created_at timestamptz not null default now());
create index if not exists booking_requests_company_date_idx on public.booking_requests(company_id,requested_date,requested_time);
alter table public.booking_settings enable row level security; alter table public.booking_services enable row level security; alter table public.booking_hours enable row level security; alter table public.booking_requests enable row level security;
